// spanInfo returns the span name and RPC attributes for a full method name
// ("/pkg.Service/Method").
func spanInfo(fullMethod string) (string, []attribute.KeyValue) {
	name := strings.TrimPrefix(fullMethod, "/")
	attrs := []attribute.KeyValue{attribute.String("rpc.system", "grpc")}
	if i := strings.LastIndex(name, "/"); i >= 0 {
		attrs = append(attrs, attribute.String("rpc.service", name[:i]), attribute.String("rpc.method", name[i+1:]))
	}
	return name, attrs
}

// serverError reports whether a status code is an error for a server span
